-- Business roles reuse the existing agent queue and execution engine.
ALTER TABLE "AgentTask" ADD COLUMN "parentTaskId" UUID REFERENCES "AgentTask"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD COLUMN "approvedInputHash" CHAR(64);
ALTER TABLE "AgentSchedule" ADD COLUMN "automationKey" VARCHAR(100) UNIQUE;
CREATE TABLE "AgentSource" ("id" UUID PRIMARY KEY,"url" VARCHAR(2048) NOT NULL UNIQUE,"title" VARCHAR(200) NOT NULL,"content" TEXT NOT NULL,"digest" CHAR(64) NOT NULL CHECK ("digest" ~ '^[a-f0-9]{64}$'),"fetchedAt" TIMESTAMPTZ(3) NOT NULL,"provenance" VARCHAR(30) NOT NULL DEFAULT 'FETCHED' CHECK ("provenance" IN ('FETCHED','TEST_FIXTURE')));
CREATE TABLE "AgentWorkProduct" ("id" UUID PRIMARY KEY,"taskId" UUID NOT NULL UNIQUE REFERENCES "AgentTask"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"kind" VARCHAR(30) NOT NULL CHECK ("kind" IN ('CEO','RESEARCHER','EDITOR','SEO','COMMERCIAL')),"body" JSONB NOT NULL,"evidence" JSONB NOT NULL DEFAULT '[]',"status" VARCHAR(30) NOT NULL DEFAULT 'PENDING_REVIEW' CHECK ("status" IN ('PENDING_REVIEW','APPROVED','REJECTED')),"reviewedAt" TIMESTAMPTZ(3),"reviewedById" UUID REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"reviewNote" VARCHAR(2000),"articleId" UUID REFERENCES "Article"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"leadId" UUID REFERENCES "CommercialLead"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "agent_product_review" CHECK ("status"='PENDING_REVIEW' OR ("reviewedAt" IS NOT NULL AND "reviewedById" IS NOT NULL AND "reviewNote" IS NOT NULL)));
CREATE INDEX "AgentWorkProduct_kind_status_createdAt_idx" ON "AgentWorkProduct"("kind","status","createdAt");
CREATE TABLE "_AgentSourceToAgentWorkProduct" ("A" UUID NOT NULL REFERENCES "AgentSource"("id") ON DELETE CASCADE ON UPDATE CASCADE,"B" UUID NOT NULL REFERENCES "AgentWorkProduct"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "_AgentSourceToAgentWorkProduct_AB_pkey" PRIMARY KEY ("A","B"));
CREATE INDEX "_AgentSourceToAgentWorkProduct_B_index" ON "_AgentSourceToAgentWorkProduct"("B");

CREATE INDEX "AgentTask_parentTaskId_idx" ON "AgentTask"("parentTaskId");
